<?php
require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../includes/classes.php'; require_role(['admin','staff']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$type=$_POST['movement_type']??'in';$note=trim($_POST['note']??'');if($pid<1||$qty<1||!in_array($type,['in','out','adjustment'],true))$error='Choose a product and enter a positive quantity.';else{$conn->begin_transaction();try{$s=$conn->prepare('SELECT stock_quantity FROM products WHERE id=? AND is_active=1 FOR UPDATE');$s->bind_param('i',$pid);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p)throw new Exception('Product not found.');$delta=$type==='in'?$qty:-$qty;$new=(int)$p['stock_quantity']+$delta;if($type==='adjustment')$new=$qty;if($new<0)throw new Exception('Stock cannot become negative.');$actualDelta=$new-(int)$p['stock_quantity'];$s=$conn->prepare('UPDATE products SET stock_quantity=? WHERE id=?');$s->bind_param('ii',$new,$pid);$s->execute();$uid=(int)current_user()['id'];$s=$conn->prepare('INSERT INTO stock_movements(product_id,user_id,movement_type,quantity_change,reference_type,notes) VALUES(?,?,?,?,?,?)');$ref='manual';$s->bind_param('iisiss',$pid,$uid,$type,$actualDelta,$ref,$note);$s->execute();log_activity($conn,'STOCK_'.$type,'products',$pid,'Quantity change '.$actualDelta.'; '.$note);$conn->commit();flash('success','Inventory updated.');redirect('staff/inventory.php');}catch(Throwable $ex){$conn->rollback();$error=$ex->getMessage();}}}
$lookup=new ProductLookup();$res=$conn->query('SELECT id,product_code,name,stock_quantity,reorder_level FROM products WHERE is_active=1 ORDER BY name');$products=$res->fetch_all(MYSQLI_ASSOC);foreach($products as $p)$lookup->add($p);
layout_header('Inventory control');
?>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="grid two section-gap"><section class="card"><h2>Record stock movement</h2><form method="post"><?= csrf_field() ?><label>Product<select name="product_id" required><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['product_code'].' — '.$p['name'].' (stock '.$p['stock_quantity'].')') ?></option><?php endforeach; ?></select></label><label>Movement type<select name="movement_type"><option value="in">Stock in</option><option value="out">Stock out</option><option value="adjustment">Set exact stock quantity</option></select></label><label>Quantity<input type="number" min="1" name="quantity" required></label><label>Notes<input name="note" maxlength="255" placeholder="Delivery, damage, correction..."></label><button class="btn">Save movement</button></form></section><section class="card"><h2>Data structure demo: Product lookup</h2><p>Products are indexed in a PHP associative array keyed by product code for quick in-memory lookup.</p><label>Test product code<input id="lookupCode" placeholder="e.g. NOODLE001"></label><button class="btn btn-outline" type="button" id="lookupButton">Find code</button><div id="lookupResult" class="result-box" aria-live="polite">Enter a product code and click Find code.</div><script>window.productLookup = <?= json_encode(array_column($products,null,'product_code'), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;</script></section></div>
<section class="card section-gap"><h2>Current inventory</h2><div class="table-wrap"><table><thead><tr><th>Code</th><th>Product</th><th>Stock</th><th>Reorder level</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?= e($p['product_code']) ?></td><td><?= e($p['name']) ?></td><td><?= (int)$p['stock_quantity'] ?></td><td><?= (int)$p['reorder_level'] ?></td><td><?= $p['stock_quantity']<=$p['reorder_level']?'<span class="badge badge-danger">Low stock</span>':'<span class="badge badge-success">OK</span>' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php layout_footer(); ?>
